import { getMdx } from '@mintlify/common/server-mdx';
import fse from 'fs-extra';
import { mkdtemp, rm } from 'fs/promises';
import { tmpdir } from 'os';
import { join } from 'path';
import { collectPackageIslands } from '../packages/collect.js';
import { DocsJsonError, InvalidPackagesError, readPackagesSetup } from '../packages/setup.js';
const PAGE = 'import { Button } from "@acme/ui";\n\n<Button label="{{label}}" />\n';
describe('package setup config references', () => {
    let docsRoot;
    beforeEach(async () => {
        docsRoot = await mkdtemp(join(tmpdir(), 'packages-setup-'));
        await fse.outputJson(join(docsRoot, 'package.json'), {
            dependencies: { '@acme/ui': '1.0.0' },
        });
    });
    afterEach(async () => {
        await rm(docsRoot, { recursive: true, force: true });
    });
    it('collects the same island ids that compilation uses with referenced variables', async () => {
        const variables = { label: 'Synthetic label' };
        await fse.outputJson(join(docsRoot, 'docs.json'), {
            packages: {},
            variables: { $ref: './variables.json' },
        });
        await fse.outputJson(join(docsRoot, 'variables.json'), variables);
        await fse.outputFile(join(docsRoot, 'page.mdx'), PAGE);
        const setup = await readPackagesSetup(docsRoot);
        const packageNames = setup?.packageNames ?? new Set();
        const collected = await collectPackageIslands({
            docsRoot,
            packageNames,
            variables: setup?.variables,
        });
        const compiled = await getMdx({
            path: 'page',
            content: PAGE,
            metadata: {},
            snippets: [],
            subdomain: 'local',
            codeStyling: undefined,
            tailwindSelectors: [],
            variables,
            packageBuild: {
                buildId: 'synthetic',
                islands: Object.fromEntries(collected.islands.map(({ id }) => [id, { prefix: `mi-${id}-`, html: '<button />' }])),
                packageNames: [...packageNames],
                packageSnippets: [...collected.packageSnippets],
            },
        });
        expect(setup?.variables).toEqual(variables);
        expect(collected.errors).toEqual([]);
        expect(collected.islands).toHaveLength(1);
        expect(compiled.parseFailed).toBeUndefined();
        expect(Object.keys(compiled.mdxExtracts.islands ?? {})).toEqual(collected.pages['page.mdx']?.ids);
    });
    it('reads referenced provider, css and ssr settings with sibling overrides', async () => {
        await fse.outputJson(join(docsRoot, 'docs.json'), {
            packages: { $ref: './packages.json', ssr: false },
        });
        await fse.outputJson(join(docsRoot, 'packages.json'), {
            provider: '/snippets\\provider.jsx',
            css: ['@acme/ui/styles.css'],
            ssr: true,
        });
        expect((await readPackagesSetup(docsRoot))?.packages).toEqual({
            provider: '/snippets/provider.jsx',
            css: ['@acme/ui/styles.css'],
            ssr: false,
        });
    });
    it('finds packages and variables in a referenced root config', async () => {
        await fse.outputJson(join(docsRoot, 'docs.json'), { $ref: './config.json' });
        await fse.outputJson(join(docsRoot, 'config.json'), {
            packages: { ssr: false },
            variables: { label: 'Synthetic label' },
        });
        const setup = await readPackagesSetup(docsRoot);
        expect(setup?.packages).toEqual({ ssr: false });
        expect(setup?.variables).toEqual({ label: 'Synthetic label' });
    });
    it.each([
        { file: 'missing.json', content: undefined, message: /does not exist/ },
        { file: 'invalid.json', content: '{', message: /contains invalid JSON/ },
    ])('reports a broken $ref to $file as a docs config error', async ({ file, content, message }) => {
        await fse.outputJson(join(docsRoot, 'docs.json'), {
            packages: { $ref: `./${file}` },
        });
        if (content !== undefined)
            await fse.outputFile(join(docsRoot, file), content);
        await expect(readPackagesSetup(docsRoot)).rejects.toThrow(DocsJsonError);
        await expect(readPackagesSetup(docsRoot)).rejects.toThrow(message);
    });
    it('keeps packages disabled when docs.json is missing', async () => {
        expect(await readPackagesSetup(docsRoot)).toBeUndefined();
    });
    it('keeps packages disabled without a packages key', async () => {
        await fse.outputJson(join(docsRoot, 'docs.json'), { name: 'Docs' });
        expect(await readPackagesSetup(docsRoot)).toBeUndefined();
    });
    it.each([
        ['', 'docs.json could not be loaded: Unexpected end of JSON input'],
        ['["packages"]', 'docs.json is not a JSON object'],
    ])('rejects docs.json %j', async (raw, message) => {
        await fse.outputFile(join(docsRoot, 'docs.json'), raw);
        await expect(readPackagesSetup(docsRoot)).rejects.toEqual(new DocsJsonError([message]));
    });
    it.each([
        ['', 'package.json is not valid JSON: Unexpected end of JSON input'],
        ['["recharts"]', 'package.json is not a JSON object'],
        ['null', 'package.json is not a JSON object'],
    ])('reports package.json %j without package names', async (raw, message) => {
        await fse.outputJson(join(docsRoot, 'docs.json'), { name: 'Docs', packages: {} });
        await fse.outputFile(join(docsRoot, 'package.json'), raw);
        const setup = await readPackagesSetup(docsRoot);
        expect(setup?.errors).toEqual([message]);
        expect(setup?.packageJsonError).toBe(message);
        expect(setup?.packageNames).toEqual(new Set());
    });
    it.each([
        ['a string', 'nope', ['docs.json packages: Expected object, received string']],
        [
            'an http registry',
            { registries: { '@acme': 'http://npm.acme.com/' } },
            [
                'docs.json packages.registries.@acme: Registry URLs must start with `https://` and then the host',
            ],
        ],
        [
            'a provider outside the docs',
            { provider: '../provider.jsx', isolation: 'none' },
            [
                'docs.json packages.provider: Provider path cannot contain `..` segments',
                "docs.json packages.isolation: Invalid enum value. Expected 'page' | 'frame', received 'none'",
            ],
        ],
    ])('rejects %s for packages with the schema errors and the variables', async (_, packages, errors) => {
        await fse.outputJson(join(docsRoot, 'docs.json'), {
            name: 'Docs',
            packages,
            variables: { label: 'Synthetic label' },
        });
        const error = await readPackagesSetup(docsRoot).catch((caught) => caught);
        expect(error).toBeInstanceOf(InvalidPackagesError);
        if (!(error instanceof InvalidPackagesError))
            return;
        expect(error.problems).toEqual(errors);
        expect(error.variables).toEqual({ label: 'Synthetic label' });
    });
    it('reports errors in a snippet a page imports', async () => {
        await fse.outputJson(join(docsRoot, 'docs.json'), { name: 'Docs', packages: {} });
        await fse.outputFile(join(docsRoot, 'charts.mdx'), 'import { Chart } from "/snippets/chart.jsx";\n\n<Chart />\n');
        await fse.outputFile(join(docsRoot, 'snippets/chart.jsx'), 'import { Button } from "@acme/ui";\n\nexport const Chart = () => <Button\n');
        const collected = await collectPackageIslands({
            docsRoot,
            packageNames: new Set(['@acme/ui']),
        });
        expect(collected.errors.some(({ file }) => file === 'snippets/chart.jsx')).toBe(true);
    });
});
